def text2int(self, textnum):
    """
    Convert the word string to the corresponding integer string
    :param textnum: string, the word string to be converted
    :return: string, the final converted integer string
    >>> w2n = Words2Numbers()
    >>> w2n.text2int("thirty-two")
    "32"
    """
    # Normalize text
    textnum = textnum.lower().replace("-", " ")
    words = textnum.split()

    result = 0
    current = 0
    scale = 100

    for word in words:
        if word in self.numwords and word != "and":
            val, unit = self.numwords[word]

            if unit == 0:
                # Scale word like hundred, thousand, million
                scale = val
            else:
                if val < 100 and unit >= 100:
                    # Compound word with scale (e.g., hundred, thousand) sets new scale
                    scale = val
                else:
                    current += val

            if val >= 100:
                current *= val
            else:
                current += val

            result += current

    return str(result)

